functions.body:
case "${1:-}" in
  1|true|TRUE|True|yes|YES|Yes) return 0 ;;
  *) return 1 ;;
esac

local target_header="${1:-}"
local notes_file="${BASH4LLM_EXTRAS_DIR:-}/docs/core-notes.sh"
if [ ! -f "$notes_file" ] || [ ! -r "$notes_file" ]; then
  return 1
fi
awk -v header="$target_header" '
  index($0, header) { flag=1; next }
  /^[[:space:]]*$/ { if (flag) { flag=0; exit } }
  flag { print }
' "$notes_file" 2>/dev/null

local code="${1:-ERROR}" msg="${2:-}" err_num=13
case "$code" in
  APIKEY|NO_KEY)   err_num="${BASH4LLM_ERR_NO_API_KEY:-10}" ;;
  BAD_MODEL|MODEL) err_num="${BASH4LLM_ERR_BAD_MODEL:-11}" ;;
  CURL|NETWORK)    err_num="${BASH4LLM_ERR_CURL_FAILED:-12}" ;;
  SYNTAX_VAL|PARSE)err_num="${BASH4LLM_ERR_PARSE:-13}" ;;
  PROMPT|NO_PROMPT)err_num="${BASH4LLM_ERR_NO_PROMPT:-14}" ;;
  TMP|STORAGE)     err_num="${BASH4LLM_ERR_TMP:-15}" ;;
  API)             err_num="${BASH4LLM_ERR_API:-16}" ;;
  SEC|SECURITY)    err_num="${BASH4LLM_ERR_SEC:-17}" ;;
esac
if is_truthy "${JSON_DIAGNOSTICS:-0}"; then
  emit_json_diagnostics "ERROR" "$err_num" "$code" "$msg"
else
  printf '%s%sERROR%s: %s: %s\n' "$(log_prefix)" "${C_RED}" "${C_RST}" "$code" "$msg" >&2
fi
if [ -n "$BASH4LLM_LOG" ]; then printf '%s ERROR %s %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$code" "$msg" >>"$BASH4LLM_LOG" 2>/dev/null || true; fi

local target_header="${1:-}"
local notes_file="${BASH4LLM_EXTRAS_DIR:-}/docs/core-notes.sh"
if [ ! -f "$notes_file" ] || [ ! -r "$notes_file" ]; then
  return 1
fi
awk -v header="$target_header" '
  index($0, header) { flag=1; next }
  /^[[:space:]]*$/ { if (flag) { flag=0; exit } }
  flag { print }
' "$notes_file" 2>/dev/null
